export function getUnitOne(courseSlug:string,unitSlug:string) { const u=unitOnes[courseSlug]; return u?.slug===unitSlug ? u : undefined; }

// Thermodynamics follows the same full teaching sequence as the detailed Physics 1 lessons.
const thermoUnit = unitOnes['physics-2'];
thermoUnit.lessons[0].equations.push('v_rms = √(3k_B T/m)', 'U = (3/2)nRT (monatomic ideal gas)');
thermoUnit.lessons[0].terms.push(['Root-mean-square speed','Square root of the mean squared particle speed; it is not the most probable speed.'],['Maxwell–Boltzmann distribution','A distribution of particle speeds; its area represents particle count or normalized probability.']);
thermoUnit.lessons.forEach(l=>{l.estimatedTime='70–100 minutes, with practice';l.objectives=guidedLessons[l.apTopic].checklist;});
thermoUnit.questions.push(
 q('The rms speed of a fixed gas increases by a factor of 3. Its kelvin temperature increases by…',['3','√3','9','1/9'],2,'The average translational energy is proportional to the mean squared speed and to T. Thus T scales by 3² = 9.'),
 q('The normalized speed distribution of the same gas is compared at a higher temperature. Which combination is correct?',['Higher peak speed, broader curve, equal total area','Higher peak speed, narrower curve, greater total area','Lower peak speed, broader curve, equal total area','Unchanged curve'],0,'Higher T shifts characteristic speeds upward and spreads the distribution. Normalization keeps total area equal to 1.'),
 q('For 0.20 mol in a rigid 5.0 L vessel, the slope of P(kPa) versus T(K) is approximately…',['0.0033 kPa/K','0.333 kPa/K','33.3 kPa/K','333 kPa/K'],1,'P(kPa) = nR T/V(L), so slope = 0.20 × 8.314/5.0 = 0.333 kPa/K. The kPa and L conversions cancel.'),
 q('A rigid sealed vessel has initial gauge pressure 100 kPa when atmospheric pressure is 100 kPa, at 300 K. At 450 K its gauge pressure is…',['150 kPa','200 kPa','300 kPa','450 kPa'],1,'Absolute initial P is 200 kPa. Scale by 450/300 to get 300 kPa absolute, then subtract 100 kPa atmospheric pressure.'),
 q('The state data for fixed amount are A: 100 kPa, 2 L; B: 200 kPa, 4 L. T_B/T_A equals…',['1','2','4','8'],2,'T ∝ PV. The PV product grows from 200 to 800 kPa·L, a factor of 4.'),
 q('A monatomic ideal gas moves between the states A: 100 kPa, 2 L and B: 200 kPa, 4 L. Its internal-energy change is…',['200 J','600 J','900 J','1300 J'],2,'U = (3/2)PV. ΔU = (3/2)(800 − 200) = 900 J because 1 kPa·L = 1 J.'),
 q('Between those same A and B states, Path I first increases pressure at 2 L then expands at 200 kPa; Path II first expands at 100 kPa then increases pressure at 4 L. Which is correct?',['ΔU is larger on Path I','Both paths have equal work','Path I needs 200 J more heat','Path II needs 200 J more heat'],2,'Work on Path I is 400 J and on Path II 200 J; vertical legs give zero work. ΔU is identical, so Q_I − Q_II = 200 J.'),
 q('A clockwise rectangular P–V loop spans 100–300 kPa and 2–4 L. Net work by the gas is…',['−400 J','+400 J','+800 J','0 J'],1,'The clockwise sign is positive, and enclosed area is (300 − 100)(4 − 2) = 400 kPa·L = 400 J.'),
 q('In an insulated mixture, object A has heat capacity 200 J/K at 80 °C and object B 400 J/K at 20 °C. With no phase change, final temperature is…',['30 °C','40 °C','50 °C','60 °C'],1,'200(T_f − 80) + 400(T_f − 20) = 0 yields T_f = 40 °C. The answer is nearer the initial temperature of the larger heat capacity.'),
 q('A Q-versus-ΔT graph for a 0.50 kg sample has slope 1000 J/K. Its specific heat is…',['500 J/(kg·K)','1000 J/(kg·K)','2000 J/(kg·K)','5000 J/(kg·K)'],2,'The slope is mc, so c = 1000/0.50 = 2000 J/(kg·K). Reversing axes would change the slope interpretation.'),
 q('An insulated ideal gas expands freely into a vacuum. Its work by the gas and internal-energy change are…',['Both zero','Both positive','Work zero, internal energy negative','Work positive, internal energy zero'],0,'Vacuum offers zero external pressure, so W_by = 0. Insulation gives Q = 0; the first law then gives ΔU = 0.'),
 q('A proposed cyclic machine absorbs 500 J from a single reservoir and converts all of it to work with no other effect. It…',['Violates energy conservation only','Satisfies both laws','Satisfies the first-law balance but violates the second law','Must be a real reversible engine'],2,'Its energy amounts balance, but a cycle with complete heat-to-work conversion from one reservoir and no other effect violates the second law.')
);
thermoUnit.freeResponse.push(
 {prompt:'Translation between representations: A fixed amount of monatomic ideal gas goes from A (2.0 L, 100 kPa) to B (4.0 L, 200 kPa). Path I raises pressure at fixed volume, then expands at 200 kPa. Path II expands at 100 kPa, then raises pressure at fixed volume. Draw both labelled paths with arrows on common axes starting at zero pressure. Calculate T_B/T_A, ΔU, work by the gas, and heat for each path. Explain why only some quantities agree.',rubric:['State PV = nRT; fixed n gives T_B/T_A = (200×4)/(100×2) = 4.','Draw Path I through (2 L, 200 kPa) and Path II through (4 L, 100 kPa), with arrows A→B.','ΔU = (3/2)Δ(PV) = 900 J for either path.','W_by,I = 400 J; W_by,II = 200 J. Fixed-volume legs do no boundary work.','Q_I = 1300 J; Q_II = 1100 J from Q = ΔU + W_by.','State that internal energy depends on endpoints while heat and work depend on path.']},
 {prompt:'Qualitative/quantitative reasoning: Two equal-particle-count samples of the same ideal gas are at 300 K and 600 K. Sketch their normalized speed distributions on common labelled axes. Compare average translational energy and rms speed. Then consider a cyclic device claiming to take heat from one reservoir and convert it all into work with no other effect. Explain separately whether its energy accounting and its spontaneous operation are consistent with the first and second laws.',rubric:['Higher-T speed curve has peak at greater speed and is broader and lower; full normalized areas are equal.','Average translational particle energy doubles because K_avg ∝ T.','Rms speed increases by √2 because v_rms ∝ √T.','A cycle has ΔU = 0; equal input heat and output work can satisfy first-law amounts.','The claimed single-reservoir heat-to-work cycle with no other effect violates the second law; conservation alone does not establish feasibility.']}
);
